'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat('et-EE',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n/100):'—';
const short=n=>new Intl.NumberFormat('et-EE',{maximumFractionDigits:2}).format(n/1e8)+' mln €';
const pct=n=>n==null?'—':new Intl.NumberFormat('et-EE',{style:'percent',maximumFractionDigits:1}).format(n);
const date=s=>new Date(s).toLocaleDateString('et-EE');
let D,S,page='ulevaade',worker,pending=new Map(),sequence=0,ready=false,busy=false,runtime='',runtimeError='',search='',filter='all',sort='id',ascending=true,selected=null,view='budget',institution='all',month='all';
const titles={ulevaade:'Ülevaade',arved:'Ostuarvete kontroll',analuus:'Eelarve ja kulud',aruanded:'Aruandlus',oppe:'Õppekeskkond'};
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,7000)}
function request(action,payload){
 if(!worker){worker=new Worker('worker.js',{type:'module'});worker.onmessage=({data})=>{const job=pending.get(data.id);if(job){clearTimeout(job.timer);pending.delete(data.id);data.error?job.reject(Error(data.error)):job.resolve(data.result)}};worker.onerror=e=>{for(const job of pending.values()){clearTimeout(job.timer);job.reject(Error(e.message||'Pythoni käivitus ebaõnnestus'))}pending.clear()};}
 return new Promise((resolve,reject)=>{const id=++sequence;const timer=setTimeout(()=>{pending.delete(id);reject(Error('Pythoni laadimine ületas 120 sekundit. Kontrolli ühendust ja proovi uuesti.'))},120000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,action,payload})});
}
async function start(){
 if(ready||busy)return;busy=true;runtimeError='';render();
 try{S=await request('start',{rows:D.invoice_seed,as_of:S.as_of});ready=true;runtime=`Python ${S.runtime.python} · Pydantic ${S.runtime.pydantic} · SQLite`;}
 catch(e){runtimeError=e.message;worker?.terminate();worker=null;}
 finally{busy=false;render();}
}
async function execute(fn){if(busy)return;busy=true;render();try{await fn()}catch(e){toast('Toiming ebaõnnestus: '+e.message)}finally{busy=false;render()}}
function runtimeBox(){return `<div class="runtime ${runtimeError?'error':''}" role="status">${busy?'◌ Töötlen Pythonis… esmane laadimine võib võtta kuni kaks minutit.':ready?'● '+esc(runtime):runtimeError?'Python ei käivitunud. '+esc(runtimeError):'Valmisnäidis on nähtav. Uute andmete kontrollimiseks käivita Python.'}${!ready&&!busy?'<button class="btn small" id="startPython">Käivita Python</button>':''}</div>`}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow muted">FINANTSARVESTUSE PRAKTIKA</div><h1>${title}</h1><p class="sub">${subtitle}</p></div><div class="heading-actions">${action}</div></div>`}
function kpis(b=D.budget[0]){return `<div class="kpis"><div class="card metric"><div class="label">Ajakohane aastaeelarve</div><div class="value">${short(b.budget_cents)}</div><div class="small">2026 · augusti väljavõtte seis</div></div><div class="card metric"><div class="label">Tegelikud kulud</div><div class="value">${short(b.actual_cents)}</div><div class="small">Jaanuar–august 2026</div></div><div class="card metric highlight"><div class="label">Aastaeelarve kasutamine</div><div class="value">${pct(b.usage)}</div><div class="small">8 kuu täitmine / aastaeelarve</div><div class="bar-track"><div style="width:${Math.min(100,b.usage*100)}%"></div></div></div><div class="card metric"><div class="label">Kasutamata aastaeelarve</div><div class="value">${short(b.remaining_cents)}</div><div class="small">Ei tähenda sama perioodi säästu</div></div></div>`}
function chart(rows=D.monthly){const W=600,H=200,max=Math.max(...rows.map(r=>r.amount_cents))*1.12,pts=rows.map((r,i)=>[46+i*(W-70)/(Math.max(1,rows.length-1)),H-25-r.amount_cents/max*(H-45)]);return `<svg class="chart" viewBox="0 0 ${W} ${H+16}" role="img" aria-label="HTM valitsemisala 2026 kuukulud ja investeeringud, amortisatsioonita">${[0,1,2,3].map(i=>{let y=H-25-i*(H-45)/3;return `<line x1="45" y1="${y}" x2="585" y2="${y}" stroke="#e6ebe4"/><text x="0" y="${y+4}">${Math.round(max*i/3/1e8)}</text>`}).join('')}<path d="M${pts.map(p=>p.join(',')).join(' L')} L${pts.at(-1)[0]},${H-25} L${pts[0][0]},${H-25} Z" fill="#e8efdd"/><path class="line" d="M${pts.map(p=>p.join(',')).join(' L')}"/>${pts.map((p,i)=>`<g><circle class="point" tabindex="0" role="button" aria-label="${rows[i].period_start}: ${euro(rows[i].amount_cents)}" data-month="${esc(rows[i].period_start)}" cx="${p[0]}" cy="${p[1]}" r="4"><title>${rows[i].period_start}: ${euro(rows[i].amount_cents)}</title></circle><text x="${p[0]}" y="${H+2}" text-anchor="middle">${['Jaan','Veebr','Märts','Apr','Mai','Juuni','Juuli','Aug','Sept'][Number(rows[i].period_start.slice(5,7))-1]}</text></g>`).join('')}</svg><div class="selection-result" id="chartSelection">Vali graafikul punkt, et näha kuu täpset summat.</div>`}
function budgetRows(){return D.budget.filter(r=>institution==='all'?r.level==='asutus':r.id===institution)}
function budgetTable(rows=D.budget.filter(r=>r.level==='asutus')){return `<div class="table-wrap"><table><thead><tr><th>Asutus</th><th class="num">Aastaeelarve</th><th class="num">Täitmine, 8 kuud</th><th class="num">Kasutamine</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td class="num">${euro(r.budget_cents)}</td><td class="num">${euro(r.actual_cents)}</td><td class="num"><span class="progress"><span style="width:${Math.min(100,r.usage*100)}%"></span></span>${pct(r.usage)}</td></tr>`).join('')}</tbody></table></div>`}
function overview(){return heading('Selge vaade finantsidele','HTM valitsemisala avalikud koondandmed ja arvete kontrolli õppesimulatsioon.',`<button class="btn" data-go="aruanded">↧ Laadi aruanne</button>`)+kpis()+`<div class="split"><section class="card"><div class="card-head"><div><h2>Kulude rütm</h2><p class="sub">Jaanuar–september 2026 · miljonites eurodes</p></div><span class="tag">Avalikud andmed</span></div>${chart()}<div class="chart-note">Kulud ja investeeringud, amortisatsioonita. Erinev arvestusalus ülal olevast eelarvevaatest.</div></section><section class="card"><div class="card-head"><div><h2>Arvete kontroll</h2><p class="sub">Kontrollpäev ${esc(S.as_of)}</p></div><span class="tag synthetic">Sünteetiline</span></div><div class="mini-stat"><span>Kontrollitud dokumente</span><strong>${S.checked}</strong></div><div class="mini-stat"><span>Vigadega dokumente</span><strong class="red">${S.erroneous_documents}</strong></div><div class="mini-stat"><span>Võimalikke duplikaatdokumente</span><strong>${S.duplicate_documents}</strong></div><p class="sub">${S.errors} blokeerivat veateadet · ${S.warnings} hoiatust. Kontroll ei tähenda arve kinnitamist.</p><button class="btn primary section-gap" data-go="arved">Ava ostuarvete kontroll →</button></section></div><section class="card section-gap"><div class="card-head"><div><h2>Eelarve kasutamine asutuste kaupa</h2><p class="sub">Ajakohane aastaeelarve võrreldes jaanuar–august täitmisega</p></div><button class="link-btn" data-go="analuus">Vaata kogu analüüsi →</button></div>${budgetTable(D.budget.filter(r=>r.level==='asutus').slice(0,4))}</section><p class="sub section-gap">Allikate hankimise viimane aeg: ${date(D.source_updated_at)} · Veebi väljavõte koostatud: ${date(D.built_at)}. Andmeid ei uuendata reaalajas.</p>`}
function invoiceRows(){const q=search.toLowerCase();return S.invoices.filter(r=>(!q||[r.id,r.raw.supplier_name,r.raw.invoice_number].join(' ').toLowerCase().includes(q))&&(filter==='all'||filter==='errors'&&r.errors>0||filter==='duplicate'&&r.issues.some(i=>i.code==='DUPLIKAAT')||filter==='warnings'&&r.warnings>0||filter==='ok'&&!r.errors)).sort((a,b)=>{let x=sort==='gross'?Number(a.raw.gross_cents):sort==='errors'?a.errors:a.id,y=sort==='gross'?Number(b.raw.gross_cents):sort==='errors'?b.errors:b.id;return (typeof x==='string'?x.localeCompare(y,'et'):(x||0)-(y||0))*(ascending?1:-1)})}
function invoiceTable(){const rows=invoiceRows();return `<p class="sub">${rows.length} / ${S.checked} dokumenti · kuvatakse viimase kontrolli tulemused</p><div class="table-wrap"><table><thead><tr><th><button class="sort-btn" data-sort="id">Dokument ↕</button></th><th>Tarnija / arvenumber</th><th class="num"><button class="sort-btn" data-sort="gross">Bruto ↕</button></th><th><button class="sort-btn" data-sort="errors">Kontroll ↕</button></th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.id)}</b><div class="sub">${esc(r.raw.invoice_date)}</div></td><td>${esc(r.raw.supplier_name)||'Puudub'}<div class="sub">${esc(r.raw.invoice_number)}</div></td><td class="num">${/^\d+$/.test(String(r.raw.gross_cents))?euro(Number(r.raw.gross_cents)):'Vigane summa'}</td><td><span class="tag ${r.errors?'red':r.warnings?'synthetic':''}">${r.errors?r.errors+' viga':r.warnings?'Hoiatused':'Korras'}</span>${r.issues.some(i=>i.code==='DUPLIKAAT')?'<div class="sub">Võimalik duplikaat</div>':''}</td><td><button class="btn small" data-detail="${esc(r.id)}">Vaata</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Sellele filtrile vastavaid dokumente pole.</div>'}</div>`}
function invoiceDetail(){const r=S.invoices.find(r=>r.id===selected);if(!r)return '';return `<section class="detail" aria-label="Arve üksikasjad"><div class="card-head"><div><h2>${esc(r.id)}</h2><p class="sub">Näidissisend · ${esc(r.raw.description)} · olek ${esc(r.status)}</p></div><button class="btn small" id="closeDetail">Sulge</button></div><p>Teenus ${esc(r.raw.service_date)} · maksetähtaeg ${esc(r.raw.due_date)} · ${esc(r.raw.cost_center)}</p><ul>${r.issues.map(i=>`<li><span class="tag ${i.severity==='VIGA'?'red':'synthetic'}">${i.severity==='VIGA'?'Viga':'Hoiatus'}</span> <code>${esc(i.code)}</code> <b>${esc(i.field)}</b><br>${esc(i.message)}</li>`).join('')||'<li>Vigu ega hoiatusi ei tuvastatud.</li>'}</ul><p class="sub">Algandmeid ei kirjutata valideerimisel ümber. Tähtaja möödumine ei tõenda tasumata olekut.</p></section>`}
function invoices(){return heading('Ostuarvete kontroll','Impordi näidisandmeid, kontrolli vigu ja vaata iga leiu põhjust.',`<span class="tag synthetic">Ainult sünteetilised õppeandmed</span>`)+runtimeBox()+`<div class="card"><div class="actions"><label class="btn">↑ Impordi CSV või XLSX<input id="fileImport" type="file" accept=".csv,.xlsx" ${!ready||busy?'disabled':''}></label><a class="btn" href="data/impordi_proov.csv" download>Laadi impordiproov</a><button class="btn" id="reset" ${busy?'disabled':''}>Taasta algne näidis</button></div><p class="sub section-gap">Fail jääb selle brauserikaardi mällu. Lehe uuendamisel lisatud arved kaovad. Kuni 500 dokumenti, fail kuni 2 MB; CSV eraldaja ;. Päris arveid siia ära sisesta.</p><details><summary>Kleebi CSV tekst</summary><p>Kohustuslikud veerud on näidisfailis. Lisa uuele dokumendile uus invoice_id.</p><textarea id="csvText" aria-label="CSV sisendtekst" placeholder="invoice_id;supplier_id;…"></textarea><button id="pasteImport" class="btn primary" ${!ready||busy?'disabled':''}>Kontrolli kleebitud CSV-d</button></details><div class="filters"><label>Otsi dokumenti või tarnijat<input id="search" type="search" value="${esc(search)}" placeholder="Näiteks DEMO-001"></label><label>Kontrolli tulemus<select id="invoiceFilter">${[['all','Kõik dokumendid'],['errors','Vigadega'],['duplicate','Võimalikud duplikaadid'],['warnings','Hoiatustega'],['ok','Blokeeriva veata']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Kontrollpäev<input type="date" id="checkDate" value="${esc(S.as_of)}"></label><button class="btn" id="recheck" ${!ready||busy?'disabled':''}>Kontrolli uuesti</button><button class="btn" data-export-invoice="csv" ${!ready||busy?'disabled':''}>CSV</button><button class="btn" data-export-invoice="xlsx" ${!ready||busy?'disabled':''}>Excel</button></div><div id="invoiceTable">${invoiceTable()}</div><div id="invoiceDetail">${invoiceDetail()}</div></div>`}
function analysisRows(){if(view==='budget')return budgetRows();if(view==='months')return D.monthly.filter(r=>month==='all'||r.period_start===month);if(view==='yoy')return D.yoy;return D.grants}
function analysis(){let rows=analysisRows();return heading('Eelarve ja kulude analüüs','Vali võrreldav vaade. Periood ja arvestusalus püsivad iga näitaja juures.')+`<div class="filters"><label>Analüüsivaade<select id="analysisView">${[['budget','Eelarve kasutamine · august'],['months','Kuukulud · jaanuar–september'],['yoy','Aastavõrdlus · 9 kuud'],['grants','Toetuste näidis · 9 kuud']].map(([v,t])=>`<option value="${v}" ${view===v?'selected':''}>${t}</option>`).join('')}</select></label>${view==='budget'?`<label>Asutus<select id="institution"><option value="all">Kõik asutused</option>${D.budget.filter(r=>r.level==='asutus').map(r=>`<option value="${r.id}" ${institution===r.id?'selected':''}>${esc(r.label)}</option>`).join('')}</select></label>`:view==='months'?`<label>Periood<select id="month"><option value="all">Kõik üheksa kuud</option>${D.monthly.map(r=>`<option value="${r.period_start}" ${month===r.period_start?'selected':''}>${r.period_start.slice(0,7)}</option>`).join('')}</select></label>`:''}<button class="btn" data-export-table="csv">Valiku CSV</button><button class="btn" data-export-table="xlsx">Valiku Excel</button></div>`+(view==='budget'?`${kpis(institution==='all'?D.budget[0]:rows[0])}<div class="card">${budgetTable(rows)}</div><div class="callout">Võrdlusalus: aasta 2026 ajakohane eelarve ja jaanuar–august täitmine. Kasutamata eelarve ei ole sama perioodi sääst. Kuupõhine kinnitatud plaan puudub.</div>`:view==='months'?`<div class="card"><div class="card-head"><div><h2>Kuukulud ja investeeringud</h2><p class="sub">HTM valitsemisala · amortisatsioonita · miljonites eurodes</p></div><span class="tag">Avalikud andmed</span></div>${chart(rows)}<div class="table-wrap"><table><thead><tr><th>Kuu</th><th class="num">Tegelik summa</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.period_start.slice(0,7)}</td><td class="num">${euro(r.amount_cents)}</td></tr>`).join('')}</tbody></table></div></div>`:view==='yoy'?`<div class="card"><h2>Kululiikide sama perioodi võrdlus</h2><p class="sub">HTM valitsemisala · jaanuar–september 2025 ja 2026 · kulud ja investeeringud amortisatsioonita</p><div class="table-wrap section-gap"><table><thead><tr><th>Kululiik</th><th class="num">2025</th><th class="num">2026</th><th class="num">Muutus</th><th class="num">%</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.level==='koond'?'HTM valitsemisala kokku':r.label)}</td><td class="num">${euro(r.previous_cents)}</td><td class="num">${euro(r.current_cents)}</td><td class="num">${euro(r.difference_cents)}</td><td class="num">${pct(r.change)}</td></tr>`).join('')}</tbody></table></div><div class="callout">Koondrida ja alamread kattuvad. Välisvahendite rahastamise ristlõiget ei liideta kuludele. Aastamuutus ei ole eelarvehälve.</div></div>`:`<div class="card"><div class="card-head"><h2>Toetuse ja perioodiplaani näidis</h2><span class="tag synthetic">Sünteetiline</span></div><div class="table-wrap"><table><thead><tr><th>Projekt</th><th class="num">Plaan</th><th class="num">Kulu</th><th class="num">Hälve</th><th class="num">Toetus</th><th class="num">Juurde maksta</th><th class="num">Tagasi nõuda</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.id)}</td><td class="num">${euro(r.budget_cents)}</td><td class="num">${euro(r.actual_cents)}</td><td class="num">${euro(r.variance_cents)}<br>${pct(r.variance)}</td><td class="num">${euro(r.earned_cents)}</td><td class="num">${euro(r.payable_cents)}</td><td class="num">${euro(r.recoverable_cents)}</td></tr>`).join('')}</tbody></table></div><div class="callout">Positiivne hälve tähendab sama perioodi plaani ületamist. Ettemakse ei ole kulu. Näidis ei tee väljamakset ega tagasinõude otsust.</div></div>`)+`<p class="sub section-gap">${view==='budget'?'Allikas TAIT2026A · August 2026 · C94:E103':view==='grants'?'Allikas: fiktiivsed toetuse tingimused, etapp3_toetused.json':'Allikas TAIT2026 · Eelarve täitmine üheksa kuud · HTM valitsemisala'}. Allika failid ja piirangud leiad aruandluse alt.</p>`}
function reports(){return heading('Aruanded, mida saab kontrollida','Valmisaruanded pärinevad Pythoni analüüsimootorist. Valikupõhine eksport toimub brauseri Pythonis.')+`<div class="download-grid"><article class="card"><div class="number-icon">01</div><h2>Finantsanalüüsi koond</h2><p class="sub">Kolme lehega vormindatud Excel: eelarve, kulud ja sünteetilised toetused.</p><div class="actions"><a class="btn primary" href="aruanded/Finantsanaluus.xlsx" download>↧ Exceli koondaruanne</a><a class="btn" href="aruanded/aruanne.md" download>Selgitus</a></div></article><article class="card"><div class="number-icon">02</div><h2>Eelarve täitmine</h2><p class="sub">Augusti 2026 täitmine ja ajakohane aastaeelarve. CSV-s on rahad sentides.</p><div class="actions"><a class="btn" href="aruanded/eelarve.csv" download>CSV</a><button class="btn" data-report="budget">Genereeri Excel</button></div></article><article class="card"><div class="number-icon">03</div><h2>Kulude koond</h2><p class="sub">2025 ja 2026 üheksa kuu võrdlus kululiikide kaupa. Koond ja detail eraldi.</p><div class="actions"><a class="btn" href="aruanded/aastavordlus.csv" download>CSV</a><button class="btn" data-report="yoy">Genereeri Excel</button></div></article><article class="card"><div class="number-icon">04</div><h2>Ostuarvete kontroll</h2><p class="sub">Seansi ${S.checked} sünteetilise dokumendi viimane kontroll. Sisaldab ka sinu imporditud näidisridu.</p><div class="actions"><button class="btn" data-export-all="csv">Genereeri CSV</button><button class="btn" data-export-all="xlsx">Genereeri Excel</button></div></article><article class="card"><div class="number-icon">05</div><h2>SQL analüüsiks</h2><p class="sub">SQLite'i analüüsiandmebaas. Ava DBeaveris ja võrdle tulemusi veebiga.</p><div class="actions"><a class="btn" href="aruanded/analuus.sqlite" download>↧ SQLite</a></div></article><article class="card"><div class="number-icon">06</div><h2>Projektifailid</h2><p class="sub">Etappide 1–4 lähtekood, testid, õppematerjal ja GitHub Pagesi avaldamisjuhend.</p><div class="actions"><a class="btn" href="Finantsarvestus_etapp4.zip" download>↧ Projekti ZIP</a></div></article></div><div class="section-gap">${runtimeBox()}</div><section class="card section-gap"><h2>Andmete päritolu</h2><p class="sub">Allikate hankimine ja veebiväljavõtte loomine on eri sündmused. Veeb ei laadi automaatselt uusi riigieelarve faile.</p><div class="source-list">${D.sources.map(s=>`<div><b>${esc(s.source_id)} · ${esc(s.publisher)}</b><br>${esc(s.period)} · ${esc(s.version_description)}<br>Hangitud ${date(s.downloaded_at)} · <a href="${esc(s.url)}" target="_blank" rel="noopener">Ametlik XLSX-allikas ↗</a></div>`).join('')}</div><p class="sub section-gap">Ametlikud koondandmed võivad hiljem muutuda. Veebiväljavõte: ${date(D.built_at)}. Arved ja toetuse tingimused on sünteetilised õppeandmed.</p></section>`}
function learning(){return heading('Õpi töö käigus','Finantsarvestuse põhimõtted, selged andmed ja kontrollitavad arvutused.')+`<section class="card"><h2>Algallikast graafikule</h2><p class="sub">Igal arvul on päritolu ja üheselt määratletud tähendus.</p><div class="flow section-gap"><b>Ametlik XLSX</b> → <b>Python + Polars</b> → <b>Kontrollitud JSON</b> → <b>Veebi graafik</b></div><p>Arve liigub teist teed: CSV/XLSX → brauseri Python → senised ärireeglid ja Pydantic → SQLite'i seanss → kontrolliaruanne.</p></section><div class="learning-grid section-gap">${[['01','Eelarve kasutamine','772,6 miljonit / 1207,5 miljonit ≈ 64%. See on kaheksa kuu täitmine jagatud terve aasta eelarvega. Sama perioodi säästu arvutamiseks on vaja kinnitatud perioodiplaani.'],['02','Kontroll ei ole kinnitus','Arvele võib jääda hoiatus teenuse ja arve erineva kuu kohta. Finantsspetsialist selgitab arvestusperioodi. Duplikaaditunnus osutab ülevaatamise vajadusele, mitte tõendatud pettusele.'],['03','Tüübid ja täpsed summad','Pydantic kontrollib andmete kuju. Raha on täisarvuna sentides, ümardused tehakse Decimal abil. True ei tohi muutuda 1 sendiks. Ärireeglid kontrollivad neto, käibemaksu ja bruto kooskõla.'],['04','Tabelid ja tehingud','Polars töötleb avalikke analüüsitabeleid enne avaldamist; pandas kontrollib kuutulemuste võrdsust. SQLite hoiab brauseri seansi dokumente ja kontrollilogi, mitte serveri andmebaasi.'],['05','Automaatne Excel','openpyxl kirjutab Pythoni arvutustulemused XLSX-faili. CSV/Exceli valikueksport kasutab hetkel valitud ridu. Failid on hetkeseisud, mitte iseenesest uuenevad aruanded.'],['06','Edasised laiendused','Tulevane API võib kasutada sama valideerimismudelit. LLM saab selgitada kontrollitud aruannet, RAG otsida juhenditest viiteid. Mudel ei kinnita arvet ega asenda deterministlikku finantsarvutust.']].map(([n,t,p])=>`<article class="card"><span class="eyebrow muted">${n} / PRAKTIKA</span><h2 class="section-gap">${t}</h2><p>${p}</p></article>`).join('')}</div><section class="card section-gap"><h2>Proovi ise</h2><p>Laadi impordiproov, impordi see arvete vaates ja leia SUMMA veakood. Ekspordi tulemus Excelisse. Täielik 30-minutiline õppemoodul sisaldab viit harjutust koos lahendustega.</p><div class="actions"><a class="btn primary" href="oppe/OPPEMOODUL_04.md" download>Õppemoodul 4</a><a class="btn" href="oppe/OPPEMOODUL_03.md" download>Finantsanalüüsi alused</a><a class="btn" href="oppe/PYDANTIC_POLARS.md" download>Tehnoloogiate näited</a></div></section>`}
function bindCharts(){document.querySelectorAll('[data-month]').forEach(el=>{const show=()=>{const r=D.monthly.find(r=>r.period_start===el.dataset.month);$('#chartSelection').textContent=`${r.period_start.slice(0,7)}: ${euro(r.amount_cents)}`};el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}})}
function bindInvoiceTable(){document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(sort===b.dataset.sort)ascending=!ascending;else{sort=b.dataset.sort;ascending=true}$('#invoiceTable').innerHTML=invoiceTable();bindInvoiceTable()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{selected=b.dataset.detail;$('#invoiceDetail').innerHTML=invoiceDetail();$('#closeDetail').onclick=()=>{selected=null;$('#invoiceDetail').innerHTML=''};$('#invoiceDetail').scrollIntoView({behavior:'smooth',block:'nearest'})});if($('#closeDetail'))$('#closeDetail').onclick=()=>{selected=null;$('#invoiceDetail').innerHTML=''}}
async function ensureReady(){if(!ready){await start();if(!ready)throw Error('Pythoni mootor ei ole valmis')}}
function download(content,name,fmt){const bytes=Uint8Array.from(atob(content),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:fmt==='csv'?'text/csv;charset=utf-8':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Aruanne on genereeritud: '+name)}
async function exportInvoices(fmt,all=false){await ensureReady();await execute(async()=>{const ids=(all?S.invoices:invoiceRows()).map(r=>r.id);const r=await request('invoice_export',{ids,fmt});download(r.content,'arvete_kontroll.'+fmt,fmt)})}
async function exportTable(rows,fmt,title){rows=rows.map(r=>({...r,provenance:r.provenance||'TULETATUD',scope:r.scope||(r.provenance==='SUNTEETILINE'?'FIKTIIVSED_PROJEKTID':'HTM_valitsemisala'),report_view:title,source_period:r.actual_period||r.period||r.period_start||'jaan-sept 2025 ja 2026'}));await ensureReady();await execute(async()=>{const r=await request('table_export',{rows,fmt,title});download(r.content,'finantsanaluusi_valik.'+fmt,fmt)})}
async function importBytes(bytes,kind){await execute(async()=>{if(bytes.length>2e6)throw Error('Faili piir on 2 MB');let binary='';for(const b of bytes)binary+=String.fromCharCode(b);S=await request('import',{content:btoa(binary),kind});toast('Import kontrollitud. Seansis on '+S.checked+' dokumenti.');selected=null})}
function render(){if(!D)return;$('#content').innerHTML=({ulevaade:overview,arved:invoices,analuus:analysis,aruanded:reports,oppe:learning}[page])();$('#crumb').textContent=titles[page];$('#navErrors').textContent=S.erroneous_documents;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$('#startPython')?.addEventListener('click',start);bindCharts();if(page==='arved'){
 $('#search').oninput=e=>{search=e.target.value;$('#invoiceTable').innerHTML=invoiceTable();bindInvoiceTable()};$('#invoiceFilter').onchange=e=>{filter=e.target.value;render()};bindInvoiceTable();$('#recheck').onclick=()=>{const as_of=$('#checkDate').value;execute(async()=>{S=await request('check',{as_of});toast('Kontroll uuendatud')})};$('#reset').onclick=()=>{worker?.terminate();worker=null;ready=false;busy=false;runtimeError='';S=structuredClone(D.invoice_snapshot);search='';filter='all';selected=null;start()};$('#fileImport').onchange=async e=>{const f=e.target.files[0];if(f)await importBytes(new Uint8Array(await f.arrayBuffer()),f.name.toLowerCase().endsWith('.xlsx')?'xlsx':'csv')};$('#pasteImport').onclick=()=>importBytes(new TextEncoder().encode($('#csvText').value),'csv');
 }if(page==='analuus'){$('#analysisView').onchange=e=>{view=e.target.value;render()};$('#institution')?.addEventListener('change',e=>{institution=e.target.value;render()});$('#month')?.addEventListener('change',e=>{month=e.target.value;render()})}
 document.querySelectorAll('[data-export-invoice]').forEach(b=>b.onclick=()=>exportInvoices(b.dataset.exportInvoice).catch(e=>toast(e.message)));document.querySelectorAll('[data-export-all]').forEach(b=>b.onclick=()=>exportInvoices(b.dataset.exportAll,true).catch(e=>toast(e.message)));document.querySelectorAll('[data-export-table]').forEach(b=>b.onclick=()=>exportTable(analysisRows(),b.dataset.exportTable,titles.analuus).catch(e=>toast(e.message)));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>exportTable(b.dataset.report==='budget'?D.budget:D.yoy,'xlsx',b.dataset.report==='budget'?'Eelarve kasutamine':'Kulude aastavõrdlus').catch(e=>toast(e.message)));
}
function navigate(p){page=titles[p]?p:'ulevaade';location.hash=page;render();window.scrollTo(0,0);if(page==='arved'&&!ready&&!busy&&!runtimeError)start()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(titles[p]&&p!==page)navigate(p)});
fetch('data/projekt.json').then(r=>{if(!r.ok)throw Error('Andmefail puudub');return r.json()}).then(d=>{D=d;S=structuredClone(D.invoice_snapshot);navigate(location.hash.slice(1)||'ulevaade')}).catch(e=>{$('#globalError').hidden=false;$('#globalError').textContent='Andmeid ei saanud laadida: '+e.message;$('#content').innerHTML='<p>Käivita leht HTTP kaudu. Kohalik juhis: python -m http.server 8000 --directory dist</p>'});
